package com.brightloop.subscription;
import com.brightloop.catalog.*;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="subscription_lines") public class SubscriptionLine{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subscription_id",nullable=false) Subscription subscription;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id",nullable=false) Product product;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="variant_id") ProductVariant variant;@Column(nullable=false,length=255) String description;@Column(nullable=false) int quantity;@Column(name="unit_price",nullable=false,precision=12,scale=2) BigDecimal unitPrice;@Column(name="tax_rate",nullable=false,precision=12,scale=4) BigDecimal taxRate=BigDecimal.ZERO;
 protected SubscriptionLine(){}public SubscriptionLine(Subscription s,Product p,ProductVariant v,String desc,int q,BigDecimal unit,BigDecimal tax){subscription=s;product=p;variant=v;description=desc;quantity=q;unitPrice=unit;taxRate=tax;}public Long getId(){return id;}public Product getProduct(){return product;}public ProductVariant getVariant(){return variant;}public String getDescription(){return description;}public int getQuantity(){return quantity;}public BigDecimal getUnitPrice(){return unitPrice;}public BigDecimal getTaxRate(){return taxRate;}
}
